using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: Keep legacy discriminator property name for existing documents
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Fix 2: Preserve legacy id format (discriminator + key) for existing documents
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .ToJsonProperty("id")
            .HasValueGenerator<LegacyIdValueGenerator>();

        // Fix 3: HasIndex() removed — Cosmos doesn't support EF-managed indexes.
        // The previous HasIndex(b => b.Name) call now throws and must be removed.
    }

    protected override void ConfigureConventions(ModelConfigurationBuilder configurationBuilder)
    {
        // Fix 2 (global): Disable the new default id-format convention
        configurationBuilder.Conventions.Remove(
            typeof(Microsoft.EntityFrameworkCore.Cosmos.Metadata.Conventions.CosmosNoDiscriminatorInIdConvention));
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

