using Microsoft.EntityFrameworkCore;

class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Fix 1: EF Core 9 renamed the discriminator property from "Discriminator" to "$type".
            // Existing documents still have "Discriminator", so we must keep the old name.
            entity.HasDiscriminator<string>("Discriminator");

            // Fix 2: EF Core 9 no longer prepends the discriminator to the "id" property.
            // Existing documents have id="Blog|1". Opt back in to include discriminator in id.
            entity.HasDiscriminatorInId();

            // Fix 3: HasIndex() now throws at runtime for Cosmos provider.
            // The previous `entity.HasIndex(b => b.Name)` must be removed entirely.
            // Cosmos indexing is managed via indexing policy on the container, not EF.
        });
    }
}

class Blog { public string Id { get; set; } public string Name { get; set; } }

